#pragma once

#include <Arduino.h>

// Larger world map for the 4.0" 320x480 board, same 2:1 equirectangular
// projection as the 300x150 map in greyline_map.h, so latLonToMapXY needs no
// change beyond the two size constants.
//
// 105,800 pixels = 211,600 bytes of flash. That is also 211,600 bytes if it is
// ever composed in a single 16-bit sprite, which will NOT allocate: the board
// reports a largest free block of about 110KB. Draw it in horizontal bands.
//
// Deliberately shares the identifiers used by greyline_map.h so the drawing
// code never has to know which map a build selected.

constexpr uint16_t kGreylineMapWidth = 460;
constexpr uint16_t kGreylineMapHeight = 230;

